const listStuckRailIntents = `-- name: ListStuckRailIntents :many

SELECT id, merchant_id, rail, intent_type, subscription_id, payment_id, price_id, payload, idempotency_key, status, attempts, next_attempt_at, claimed_until, origin, origin_reason, actor, last_failure_reason, expires_at, result_evidence, created_at, executed_at, updated_at, psp_id, destructive_run_id, custodian_id FROM openrails.rail_intents
WHERE (status IN ('pending', 'failed_retryable') AND created_at <= $1::timestamptz)
   OR (status IN ('in_flight', 'unknown_needs_verify') AND created_at <= $2::timestamptz)
ORDER BY created_at, id
`

type ListStuckRailIntentsParams struct {
	ActionCutoff time.Time
	VerifyCutoff time.Time
}

// ============================================================================
// Reconcile (#107 PS-10): stuck-intent detection
// ============================================================================
// Non-terminal intents that have sat in the ledger beyond the reconcile
// engine's hardcoded stuck thresholds: pending/failed_retryable older than the
// action cutoff (24h), in_flight/unknown_needs_verify older than the verify
// cutoff (2h — a healthy verifier resolves unknowns in minutes; an in_flight
// lease outliving hours means a dead executor). Read-only; runs tenant-scoped
// on the engine's tenant-pinned connection.
func (q *Queries) ListStuckRailIntents(ctx context.Context, arg ListStuckRailIntentsParams) ([]OpenrailsRailIntent, error) {
	rows, err := q.db.Query(ctx, listStuckRailIntents, arg.ActionCutoff, arg.VerifyCutoff)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OpenrailsRailIntent
	for rows.Next() {
		var i OpenrailsRailIntent
		if err := rows.Scan(
			&i.ID,
			&i.MerchantID,
			&i.Rail,
			&i.IntentType,
			&i.SubscriptionID,
			&i.PaymentID,
			&i.PriceID,
			&i.Payload,
			&i.IdempotencyKey,
			&i.Status,
			&i.Attempts,
			&i.NextAttemptAt,
			&i.ClaimedUntil,
			&i.Origin,
			&i.OriginReason,
			&i.Actor,
			&i.LastFailureReason,
			&i.ExpiresAt,
			&i.ResultEvidence,
			&i.CreatedAt,
			&i.ExecutedAt,
			&i.UpdatedAt,
			&i.PspID,
			&i.DestructiveRunID,
			&i.CustodianID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

